SELECT 'missing_admin_after_activation' AS rule,COUNT(*) AS violations FROM institution_provisioning p JOIN institution i ON i.id=p.institution_id
 WHERE i.status='active' AND NOT EXISTS(SELECT 1 FROM institution_membership m JOIN user u ON u.id=m.user_id JOIN institution_membership_role r ON r.membership_id=m.id AND r.role='InstitutionAdmin' JOIN institution_membership_security_state s ON s.institution_id=m.institution_id AND s.membership_id=m.id WHERE m.institution_id=i.id AND m.status='active' AND s.security_generation>=0)
UNION ALL SELECT 'invalid_invitation',COUNT(*) FROM institution_invitation WHERE status NOT IN ('pending','consumed','revoked') OR attempts NOT BETWEEN 0 AND 5 OR (status='consumed')<>(consumed_membership_id IS NOT NULL)
UNION ALL SELECT 'invalid_approval',COUNT(*) FROM institution_provisioning p JOIN institution_onboarding_event e ON e.institution_id=p.institution_id AND e.id=p.approval_event_id WHERE e.actor_kind<>'Operator' OR e.action<>'Provision'
UNION ALL SELECT 'invalid_nonce_actor',COUNT(*) FROM platform_operation_nonce n JOIN institution_onboarding_event e ON e.institution_id=n.institution_id AND e.id=n.event_id WHERE e.actor_kind<>'Operator' OR e.operator_id<>n.operator_id
UNION ALL SELECT 'missing_c_tables',ABS(4-COUNT(*)) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('institution_provisioning','institution_invitation','institution_onboarding_event','platform_operation_nonce');
